const MODS = { mgt, eco, compta, math, num, fr, en, metho };

const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const pick = a => a[Math.floor(Math.random() * a.length)];
const shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
const r2 = (x, d = 2) => Math.round(x * 10 ** d) / 10 ** d;
// عرض الأرقام حسب اللغة
export function nf(x, d = 2) { const v = r2(x, d); const s = v.toLocaleString(lang === 'en' ? 'en-US' : 'fr-FR', { maximumFractionDigits: d }); return s.replace(/ | /g, ' '); }
const DH = () => tr('DH', 'درهم', 'MAD');
const steps = arr => `<ol>${arr.map(s => `<li>${s}</li>`).join('')}</ol>`;
const F = s => `<span class="f">${s}</span>`;

// تمرين حسابي
function calc(mod, title, q, ans, sol, o = {}) { return { mod, title, type: 'num', q, ans, sol, unit: o.unit || '', tol: o.tol ?? Math.max(0.011, Math.abs(ans) * 0.005), }; }
// تمرين اختيار من متعدد
function mcq(mod, title, q, good, bad, sol) {
  const uniq = [...new Set(bad.map(String))].filter(b => b !== String(good)).slice(0, 3);
  const opts = shuffle([String(good), ...uniq]);
  return { mod, title, type: 'mcq', q, opts, ans: opts.indexOf(String(good)), sol };
}
export function checkAns(e, v) {
  let s = String(v).trim().replace(/\s| | |dh|mad|درهم|%/gi, '');
  if (s.includes(',') && s.includes('.')) s = s.replace(/,/g, ''); else s = s.replace(',', '.');
  const x = parseFloat(s); if (!isFinite(x)) return false;
  return Math.abs(x - e.ans) <= e.tol;
}

