function glossDef(mid) { const g = MODS[mid].gloss; const c = pick(g); const others = shuffle(g.filter(x => x !== c)).slice(0, 3);
  const term = x => lang === 'ar' ? x[1] : lang === 'en' ? x[2] : x[0];
  return mcq(mid, tr('Vocabulaire', 'المصطلحات', 'Vocabulary'), tr('Quel terme correspond à cette définition ?', 'أشمن مصطلح كيوافق هاد التعريف؟', 'Which term matches this definition?') + `<br><b>« ${L(c[3])} »</b>`, term(c), others.map(term), `<p><b>${c[0]}</b> · <span dir="rtl">${c[1]}</span> · <i>${c[2]}</i></p><p>${L(c[3])}</p>`); }
function glossTr(mid) { const g = MODS[mid].gloss; const c = pick(g); const others = shuffle(g.filter(x => x !== c)).slice(0, 3); const toEn = Math.random() < 0.5;
  return mcq(mid, tr('Traduction', 'الترجمة', 'Translation'), toEn ? tr(`Comment dit-on « ${c[0]} » en anglais ?`, `كيفاش كنقولو «${c[0]}» بالإنجليزية؟`, `What is “${c[0]}” in English?`) : tr(`Que signifie « ${c[0]} » en arabe ?`, `شنو معنى «${c[0]}» بالعربية؟`, `What does “${c[0]}” mean in Arabic?`), toEn ? c[2] : c[1], others.map(x => toEn ? x[2] : x[1]), `<p>${c[0]} = <b>${toEn ? c[2] : c[1]}</b></p><p>${L(c[3])}</p>`); }

