export const GENS = { math: G_MATH, eco: G_ECO, compta: G_CPT, num: G_NUM, mgt: G_MGT, fr: G_FR, en: G_EN, metho: G_MET };
// تمرين جديد: المادة (ولا all)، النوع mix/calc/qcm
export function makeEx(mod, type = 'mix') {
  const mods = mod && mod !== 'all' ? [mod] : Object.keys(GENS);
  for (let k = 0; k < 20; k++) {
    const m = pick(mods); let pool = GENS[m].filter(g => type === 'mix' || g.t === type);
    const useGloss = type !== 'calc' && (Math.random() < (type === 'qcm' ? 0.3 : 0.2) || !pool.length);
    if (!pool.length && type === 'calc') { if (mods.length === 1) pool = GENS[m]; else continue; }
    try { const e = useGloss ? (Math.random() < 0.6 ? glossDef(m) : glossTr(m)) : pick(pool).f(); if (e && (e.type !== 'mcq' || e.opts.length >= 2)) return e; } catch (err) { console.error(err); }
  }
  return glossDef(mods[0]);
}
